  if (!Array.isArray(costs) || costs.length < 1 || costs.length > 100000) return 'costs needs 1 to 10^5 prices.';
  if (costs.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each price is an integer from 1 to 10^5.';
  if (!Number.isInteger(coins) || coins < 1 || coins > 100000000) return 'coins is an integer from 1 to 10^8.';
  return null;
}

