function maxIceCream(costs, coins) {
  const maxCost = Math.max(...costs);
  const count = new Array(maxCost + 1).fill(0);
  for (const cost of costs) {
    count[cost]++;
  }
  let bought = 0;
  for (let price = 1; price <= maxCost && coins >= price; price++) {
    const take = Math.min(count[price], Math.floor(coins / price));
    bought += take;
    coins -= take * price;
  }
  return bought;
}

