function maxIceCream(costs, coins) {
  // Try every subset of bars and keep the largest affordable one.
  const n = costs.length;
  let best = 0;
  for (let mask = 0; mask < 1 << n; mask++) {
    let total = 0;
    let size = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        total += costs[i];
        size++;
      }
    }
    if (total <= coins && size > best) best = size;
  }
  return best;
}

