function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const top = rand() < 0.5 ? 100000 : 50;
    const costs = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
    const total = costs.reduce((a, b) => a + b, 0);
    const coins = Math.max(1, Math.min(100000000, Math.floor(rand() * total * 1.1)));
    return [costs, coins];
  }
  const n = 1 + Math.floor(rand() * 10);
  const top = rand() < 0.7 ? 10 : 100000;
  const costs = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const total = costs.reduce((a, b) => a + b, 0);
  const coins = Math.max(1, Math.min(100000000, Math.floor(rand() * (total + 3))));
  return [costs, coins];
}
